\draw[black] (0.5,-0.04)--(0.5,0.04);
\node[below,font=\fontsize{8.5}{10}\selectfont] at (0.5,-0.04) {$\frac12$};
\node[above left,font=\fontsize{8.5}{10}\selectfont] at (0,1.5707963268) {$\frac{\pi}{2}$};
